  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B016",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattices turned ultracold atoms into controllable quantum many-body systems, making important condensed-matter phenomena experimentally accessible and establishing quantum simulation as a powerful physics method.",
        "attribution": "Bloch and Greiner led landmark experiments demonstrating lattice-based many-body physics; Zoller supplied central theoretical ideas. The experimental and theoretical contributions are complementary.",
        "maturity": "A sustained body of experiments has established the platform and produced results across many years.",
        "uncertainties": [
          "The broader impact of analog quantum simulation relative to other routes to understanding many-body systems remains open."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit quantum electrodynamics created a new regime for controlling and measuring light-matter interactions, bringing quantum optics into engineered superconducting circuits and enabling a major experimental research platform.",
        "attribution": "Blais developed key theory connecting circuits to cavity QED; Wallraff and Schoelkopf were central to early experimental realization and development. The long contribution list makes a three-person boundary difficult.",
        "maturity": "The framework has been replicated, extended, and used widely for more than two decades, supporting a mature case.",
        "uncertainties": [
          "The 2025 recognition of superconducting-circuit physics may affect how the distinct contribution of circuit QED is judged."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B055",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed how quantum information can be protected against noise in principle, transforming quantum computation from a fragile idea into a physically meaningful long-term research program.",
        "attribution": "Shor and Steane independently established pivotal codes, while Kitaev developed influential topological approaches. These are distinct contributions to a broad conceptual achievement.",
        "maturity": "The theory is well established, with increasingly strong experimental demonstrations of error correction and fault-tolerant ingredients.",
        "uncertainties": [
          "Large-scale fault-tolerant computation has not yet been demonstrated, so the ultimate practical reach remains uncertain."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B037",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks combined ultranarrow optical transitions with control of atomic motion, creating clocks of extraordinary precision and opening new ways to test fundamental physics.",
        "attribution": "Katori and Ye independently pioneered complementary approaches and led major experimental advances.",
        "maturity": "The technology has matured through sustained improvements and independent implementations, with clear scientific uses beyond timekeeping.",
        "uncertainties": [
          "The balance between fundamental measurement science and the technical achievement of building superior clocks may shape the prize case."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B023",
      "proposed_laureates": [
        "Kenneth J. Schafer",
        "Maciej Lewenstein",
        "Paul B. Corkum"
      ],
      "assessment": {
        "nobel_worthiness": "The recollision model gave a powerful physical account of high-harmonic generation and helped establish a route to probing electron motion on attosecond timescales.",
        "attribution": "Corkum's recollision picture and the theoretical work of Lewenstein and Schafer were central to explaining and developing the field; precise allocation across the model's development is challenging.",
        "maturity": "The framework has been tested and used broadly in strong-field and attosecond science for decades.",
        "uncertainties": [
          "The discovery and explanation were built through closely connected experimental and theoretical work, complicating a narrow attribution."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B061",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Work with trapped ions and ultracold atoms established core ideas and demonstrations for quantum information processing and simulation, creating a lasting bridge between quantum theory and controllable experiments.",
        "attribution": "Cirac and Zoller developed influential theoretical proposals; Blatt's experiments demonstrated and advanced quantum control with trapped ions. The candidate joins achievements across platforms and subfields.",
        "maturity": "The foundations have been repeatedly confirmed and expanded, though full-scale quantum computing remains in development.",
        "uncertainties": [
          "The breadth of the stated discovery risks combining several contributions that may warrant separate recognition."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Allan H. MacDonald",
        "Pablo Jarillo-Herrero",
        "Rafi Bistritzer"
      ],
      "assessment": {
        "nobel_worthiness": "Magic-angle twisted bilayer graphene revealed that moiré structures can produce narrow bands and rich correlated phases in a tunable solid-state system, creating a major new direction in condensed-matter physics.",
        "attribution": "Bistritzer and MacDonald predicted the key band flattening; Jarillo-Herrero's group discovered correlated insulating and superconducting behavior. Theory and experiment have distinct, identifiable roles.",
        "maturity": "The platform has generated extensive follow-up work, but the interpretation and reproducibility of some reported phases continue to develop.",
        "uncertainties": [
          "The mechanism and generality of superconductivity in this material remain unsettled."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B039",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum spin Hall effect and topological-insulator concept established a broad framework for new electronic phases protected by topology, with a clear prediction-to-experiment arc.",
        "attribution": "Kane and Mele supplied foundational theory, while Molenkamp's experiments provided a landmark realization. The wider development involved substantial contributions from other researchers.",
        "maturity": "The initial discoveries are well established, although the scope of practical impact of particular material platforms is still evolving.",
        "uncertainties": [
          "The extent to which the specific early materials represent robust, broadly useful realizations of the predicted phases remains debated."
        ]
      }
    }
  ]
}
